ALTER TABLE public.newsletter_subscribers ADD COLUMN preferred_regions text[] NOT NULL DEFAULT '{}', ADD COLUMN preferred_neighborhoods text[] NOT NULL DEFAULT '{}';
ALTER TABLE public.usuarios_publicos ADD COLUMN preferred_regions text[] NOT NULL DEFAULT '{}', ADD COLUMN preferred_neighborhoods text[] NOT NULL DEFAULT '{}';
UPDATE public.newsletter_subscribers SET preferred_regions = CASE WHEN preferred_region IS NULL THEN '{}'::text[] ELSE ARRAY[preferred_region] END, preferred_neighborhoods = CASE WHEN preferred_neighborhood IS NULL THEN '{}'::text[] ELSE ARRAY[preferred_neighborhood] END;
UPDATE public.usuarios_publicos SET preferred_regions = CASE WHEN preferred_region IS NULL THEN '{}'::text[] ELSE ARRAY[preferred_region] END, preferred_neighborhoods = CASE WHEN preferred_neighborhood IS NULL THEN '{}'::text[] ELSE ARRAY[preferred_neighborhood] END;
ALTER TABLE public.newsletter_subscribers ADD CONSTRAINT newsletter_regions_array_valid CHECK (preferred_regions <@ ARRAY['Centro','Zona Sul','Grande Tijuca','Zona Norte','Ilha do Governador','Jacarepaguá','Barra e Recreio','Zona Oeste']::text[]), ADD CONSTRAINT newsletter_all_array_exclusive CHECK (NOT all_regions OR (cardinality(preferred_regions) = 0 AND cardinality(preferred_neighborhoods) = 0));
ALTER TABLE public.usuarios_publicos ADD CONSTRAINT publico_regions_array_valid CHECK (preferred_regions <@ ARRAY['Centro','Zona Sul','Grande Tijuca','Zona Norte','Ilha do Governador','Jacarepaguá','Barra e Recreio','Zona Oeste']::text[]), ADD CONSTRAINT publico_all_array_exclusive CHECK (NOT all_regions OR (cardinality(preferred_regions) = 0 AND cardinality(preferred_neighborhoods) = 0));
COMMENT ON COLUMN public.newsletter_subscribers.preferred_regions IS 'Explicit multi-select notification regions; neighborhoods remain separately targeted.';
COMMENT ON COLUMN public.usuarios_publicos.preferred_regions IS 'Explicit multi-select notification regions, independent from home address and consent.';